 "content": "from collections import Counter

def transform(grid):
    """Replace the overlaid 3s with their 4-way symmetric background colors."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            orbit = {(r, c), (h - 1 - r, c), (r, w - 1 - c), (h - 1 - r, w - 1 - c)}
            if orbit in seen:
                continue
            seen.add(frozenset(orbit))
            vals = [grid[rr][cc] for rr, cc in orbit]
            clean = [v for v in vals if v != 3]
            if clean:
                counts = Counter(clean)
                # Most frequent unoccluded value gives the underlying symmetric cell.
                value = max(counts, key=lambda v: (counts[v], -v))
                for rr, cc in orbit:
                    if grid[rr][cc] == 3:
                        out[rr][cc] = value
    return out
